#!/usr/bin/env python3\n\"\"\"\nTest script for distance calculator functionality.\nTests the API endpoints and distance calculations.\n\"\"\"\n\nimport requests\nimport json\n\ndef test_distance_calculator():\n    \"\"\"Test the distance calculator functionality.\"\"\"\n    \n    print(\"🧪 Testing Distance Calculator\")\n    print(\"=\" * 40)\n    \n    base_url = \"http://localhost:8000\"\n    \n    try:\n        # Test 1: Get projects\n        print(\"\\n1️⃣ Getting projects...\")\n        projects_response = requests.get(f\"{base_url}/api/gis/project-locations\")\n        if projects_response.status_code != 200:\n            print(f\"❌ Failed to get projects: {projects_response.status_code}\")\n            return False\n        \n        projects = projects_response.json()\n        projects_with_coords = [p for p in projects if p.get('latitude') and p.get('longitude')]\n        \n        if not projects_with_coords:\n            print(\"❌ No projects with coordinates found\")\n            return False\n        \n        project = projects_with_coords[0]\n        print(f\"   ✅ Found project: {project['name']} at {project['latitude']}, {project['longitude']}\")\n        \n        # Test 2: Get suppliers\n        print(\"\\n2️⃣ Getting suppliers...\")\n        suppliers_response = requests.get(f\"{base_url}/api/gis/supplier-locations\")\n        if suppliers_response.status_code != 200:\n            print(f\"❌ Failed to get suppliers: {suppliers_response.status_code}\")\n            return False\n        \n        suppliers = suppliers_response.json()\n        suppliers_with_coords = [s for s in suppliers if s.get('latitude') and s.get('longitude')]\n        \n        print(f\"   ✅ Found {len(suppliers_with_coords)} suppliers with coordinates\")\n        \n        # Test 3: Calculate nearest suppliers\n        print(\"\\n3️⃣ Testing nearest suppliers API...\")\n        nearest_response = requests.get(f\"{base_url}/api/gis/nearest-suppliers/{project['id']}?limit=5\")\n        if nearest_response.status_code != 200:\n            print(f\"❌ Nearest suppliers API error: {nearest_response.status_code}\")\n            print(nearest_response.text)\n            return False\n        \n        nearest_data = nearest_response.json()\n        print(f\"   ✅ Nearest suppliers API working!\")\n        print(f\"   📍 Project: {nearest_data['project']['name']}\")\n        print(f\"   🏪 Found {len(nearest_data['nearest_suppliers'])} nearest suppliers:\")\n        \n        for i, supplier in enumerate(nearest_data['nearest_suppliers']):\n            print(f\"      {i+1}. {supplier['name']}: {supplier['distance_formatted']}\")\n        \n        # Test 4: Calculate project distances (all suppliers)\n        print(\"\\n4️⃣ Testing project distances API...\")\n        distances_response = requests.get(f\"{base_url}/api/gis/project-distances/{project['id']}\")\n        if distances_response.status_code != 200:\n            print(f\"❌ Project distances API error: {distances_response.status_code}\")\n            print(distances_response.text)\n            return False\n        \n        distances_data = distances_response.json()\n        print(f\"   ✅ Project distances API working!\")\n        print(f\"   📊 Calculated distances to {len(distances_data['suppliers'])} suppliers\")\n        \n        # Test 5: Distance matrix\n        print(\"\\n5️⃣ Testing distance matrix API...\")\n        matrix_response = requests.get(f\"{base_url}/api/gis/distance-matrix\")\n        if matrix_response.status_code != 200:\n            print(f\"❌ Distance matrix API error: {matrix_response.status_code}\")\n            print(matrix_response.text)\n            return False\n        \n        matrix_data = matrix_response.json()\n        print(f\"   ✅ Distance matrix API working!\")\n        print(f\"   📊 Matrix for {matrix_data['projects_count']} projects and {matrix_data['suppliers_count']} suppliers\")\n        \n        # Test 6: Dashboard accessibility\n        print(\"\\n6️⃣ Testing dashboard...\")\n        dashboard_response = requests.get(f\"{base_url}/\")\n        if dashboard_response.status_code != 200:\n            print(f\"❌ Dashboard error: {dashboard_response.status_code}\")\n            return False\n        \n        content = dashboard_response.text\n        if 'nearest-suppliers-content' in content:\n            print(\"   ✅ Dashboard has distance calculator section\")\n        else:\n            print(\"   ❌ Dashboard missing distance calculator section\")\n        \n        if 'loadNearestSuppliers' in content:\n            print(\"   ✅ Dashboard has distance calculation functions\")\n        else:\n            print(\"   ❌ Dashboard missing distance calculation functions\")\n        \n        print(\"\\n🎉 All distance calculator tests passed!\")\n        print(\"\\n📋 Summary:\")\n        print(f\"   • Projects with coordinates: {len(projects_with_coords)}\")\n        print(f\"   • Suppliers with coordinates: {len(suppliers_with_coords)}\")\n        print(f\"   • Distance calculation APIs: ✅\")\n        print(f\"   • Dashboard integration: ✅\")\n        \n        print(\"\\n🗺️ You can now:\")\n        print(\"   1. View the dashboard at: http://localhost:8000\")\n        print(\"   2. Select a project in the 'Nearest Suppliers' section\")\n        print(\"   3. Click 'Calculate' to see distances to suppliers\")\n        \n        return True\n        \n    except requests.exceptions.ConnectionError:\n        print(\"❌ Connection error: Make sure the server is running on port 8000\")\n        return False\n    except Exception as e:\n        print(f\"❌ Unexpected error: {e}\")\n        import traceback\n        traceback.print_exc()\n        return False\n\nif __name__ == \"__main__\":\n    success = test_distance_calculator()\n    if not success:\n        exit(1)\n"